def _parse_json(raw: bytes, status: int) -> object:
    try:
        return json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise _Incomplete(f"HTTP {status} response body is not valid JSON") from error


def _check_response(response: HttpResponse, operation: OperationFacts) -> None:
    """A response the operation accepts as its own: its declared success status."""
    status = response.status
    if 300 <= status < 400:
        raise _Incomplete(f"{operation.operation_id} received an undeclared redirect")
    if not 200 <= status < 300:
        payload = _parse_json(response.read(), status)
        metadata = payload.get("metadata") if isinstance(payload, dict) else None
        error = None
        if (
            isinstance(payload, dict) and payload.get("success") is False
            and isinstance(metadata, dict) and isinstance(metadata.get("requestId"), str)
        ):
            error = _service_error(payload.get("error"), metadata["requestId"], response.headers)
        if error is None:
            raise _Incomplete(f"HTTP {status} error body is not a service error envelope")
        raise _ServiceAnswer(status, error)
    if status != operation.success_http_status:
        raise _Incomplete(f"expected HTTP {operation.success_http_status}, got {status}")


def _service_error(payload: object, request_id: str | None, headers: Mapping[str, str]) -> ServiceError | None:
    """The service error a canonical error object carries; unknown fields are ignored."""
    if not isinstance(payload, dict):
        return None
    error_type = payload.get("errorType")
    code = payload.get("errorCode")
    message = payload.get("message")
    resource = payload.get("resource")
    retry_after = payload.get("retryAfterSecs")
    if not isinstance(error_type, str) or error_type not in contract.ERROR_TYPES:
        return None
    if not isinstance(code, str) or not isinstance(message, str):
        return None
    if resource is not None and not isinstance(resource, str):
        return None
    if retry_after is not None and (not isinstance(retry_after, int) or isinstance(retry_after, bool) or retry_after < 0):
        return None
    try:
        details = _require_json_value(payload.get("details"), "service error details")
    except ValueError:
        return None
    return ServiceError(
        error_type=error_type,
        error_code=code,
        message=message,
        details=details,
        resource=resource,
        retry_after_seconds=retry_after,
        request_id=request_id,
        traceparent=headers.get(contract.TRACEPARENT_HEADER),
        tracestate=headers.get(contract.TRACESTATE_HEADER),
    )


class _GuardedBody(io.RawIOBase):
    """A binary response body read under the call's budget; a body that
    breaks off or ends short raises ``AionixCallError``."""

    def __init__(self, response: HttpResponse, call: _Call) -> None:
        super().__init__()
        self._response = response
        self._call = call

    def readable(self) -> bool:
        return True

    def readinto(self, buffer) -> int:  # type: ignore[override]
        try:
            data = self._response.read(len(buffer))
        except BudgetElapsed as elapsed:
            self._response.close()
            raise self._call.failure(IncompleteFailure("the time budget ended while reading the binary body", elapsed)) from None
        except TransportFailure as broken:
            self._response.close()
            raise self._call.failure(IncompleteFailure(f"binary response body read failed: {broken}", broken)) from None
        buffer[: len(data)] = data
        return len(data)

    def close(self) -> None:
        if not self.closed:
            self._response.close()
        super().close()


class _EventStream:
    """The JSON events of an accepted event-stream response. A stream that
    ends does so at its end event; a close before it, an event after it, an
    event cut off by the close and an event larger than the limit are
    incomplete. A failure event ends the stream with its service error."""

    __slots__ = ("_response", "_end", "_call", "_data", "_data_bytes", "_event", "_ended", "_closed")

    def __init__(self, response: HttpResponse, end: EventStreamEnd, call: _Call) -> None:
        self._response = response
        self._end = end
        self._call = call
        self._data: list[str] = []
        self._data_bytes = 0
        self._event = ""
        self._ended = False
        self._closed = False

    def __iter__(self) -> _EventStream:
        return self

    def _broken(self, message: str, cause: BaseException | None = None) -> AionixCallError:
        self.close()
        return self._call.failure(IncompleteFailure(message, cause))

    def __next__(self) -> JsonValue:
        if self._closed:
            raise StopIteration
        operation_id = self._call.operation.operation_id
        while True:
            try:
                raw_line = self._response.readline(contract.EVENT_STREAM_MAX_EVENT_BYTES + 2)
            except BudgetElapsed as elapsed:
                raise self._broken(f"{operation_id} stream outlasted the time budget", elapsed) from None
            except TransportFailure as broken:
                raise self._broken(f"{operation_id} stream read failed: {broken}", broken) from None
            if raw_line == b"":
                if self._data:
                    raise self._broken(f"{operation_id} stream closed inside an event")
                if not self._ended and self._end.pointer is not None:
                    raise self._broken(f"{operation_id} stream closed before its end event")
                self.close()
                raise StopIteration
            if not raw_line.endswith(b"\n"):
                if len(raw_line) > contract.EVENT_STREAM_MAX_EVENT_BYTES:
                    raise self._broken(f"{operation_id} stream event exceeds the event size limit")
                raise self._broken(f"{operation_id} stream closed inside an event")
            try:
                line = raw_line.decode("utf-8").rstrip("\r\n")
            except UnicodeDecodeError as error:
                raise self._broken(f"{operation_id} stream is not valid UTF-8", error) from None
            if line == "":
                event = self._event
                self._event = ""
                if not self._data:
                    continue
                payload = "\n".join(self._data)
                self._data.clear()
                self._data_bytes = 0
                try:
                    decoded = json.loads(payload)
                except json.JSONDecodeError as error:
                    raise self._broken(f"{operation_id} stream event is not valid JSON", error) from None
                if event == contract.STREAM_FAILURE_EVENT:
                    error = _service_error(decoded, None, self._response.headers)
                    if error is None:
                        raise self._broken(f"{operation_id} stream failure is not a service error")
                    self.close()
                    raise self._call.failure(ServiceErrorFailure(http_status=self._response.status, error=error))
                if self._ended:
                    raise self._broken(f"{operation_id} stream continued after its end event")
                try:
                    value = _require_json_value(decoded, "event stream payload")
                except ValueError as error:
                    raise self._broken(f"{operation_id} stream event is not JSON", error) from None
                self._ended = self._end.is_end(value)
                return value
            elif line.startswith("data:"):
                data = line[6:] if line.startswith("data: ") else line[5:]
                self._data_bytes += len(data.encode("utf-8")) + 1
                if self._data_bytes > contract.EVENT_STREAM_MAX_EVENT_BYTES:
                    raise self._broken(f"{operation_id} stream event exceeds the event size limit")
                self._data.append(data)
            elif line.startswith("event:"):
                self._event = line[6:].strip()

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self._response.close()

    def __enter__(self) -> _EventStream:
        return self

    def __exit__(self, exc_type: object, exc_value: object, traceback: object) -> None:
        self.close()


def _ensure_parameter_set(operation: OperationFacts, location: str, values: Mapping[str, object]) -> dict[str, ParameterFacts]:
    facts = {parameter.wire_name: parameter for parameter in operation.parameters if parameter.location == location}
    unknown = set(values) - set(facts)
    if unknown:
        raise ValueError(f"{operation.operation_id} received unknown {location} parameters: {sorted(unknown)!r}")
    missing = [name for name, fact in facts.items() if fact.required and name not in values]
    if missing:
        raise ValueError(f"{operation.operation_id} is missing required {location} parameters: {missing!r}")
    return facts


def _build_path(operation: OperationFacts, values: Mapping[str, object]) -> str:
    facts = _ensure_parameter_set(operation, "path", values)
    path = operation.path_template
    for wire_name, value in values.items():
        _validate_primitive_parameter(value, facts[wire_name].type_id, wire_name)
        path = path.replace(f"{{{wire_name}}}", _encode_path_parameter(value))
    if re.search(r"\{[^{}]+\}", path):
        raise ValueError(f"{operation.operation_id} has an unresolved path template")
    return path


def _build_query(operation: OperationFacts, values: Mapping[str, object]) -> str:
    """The query string: a list is the parameter repeated, a scalar its text
    and a structured value its JSON."""
    facts = _ensure_parameter_set(operation, "query", values)
    pairs: list[tuple[str, str]] = []
    for wire_name, value in values.items():
        for item in value if isinstance(value, list) else [value]:
            _validate_primitive_parameter(item, facts[wire_name].type_id, wire_name)
            pairs.append((wire_name, _query_scalar(item)))
    return f"?{urlencode(pairs)}" if pairs else ""


_INTEGER_TYPES = frozenset({
    "contracts.core.Int64", "contracts.core.UInt64", "contracts.core.Int32", "contracts.core.UInt32",
})


def _validate_primitive_parameter(value: object, type_id: str, wire_name: str) -> None:
    if type_id == "contracts.core.String" and not isinstance(value, str):
        raise TypeError(f"parameter {wire_name!r} requires str")
    if type_id == "contracts.core.Bool" and not isinstance(value, bool):
        raise TypeError(f"parameter {wire_name!r} requires bool")
    if type_id in _INTEGER_TYPES and (not isinstance(value, int) or isinstance(value, bool)):
        raise TypeError(f"parameter {wire_name!r} requires int")


def _encode_path_parameter(value: object) -> str:
    return quote(_scalar(value), safe="")


def _query_scalar(value: object) -> str:
    if value is None:
        raise ValueError("query parameter values cannot be null")
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("query parameter numbers must be finite")
    if isinstance(value, (int, float)):
        return str(value)
    return json.dumps(_require_json_value(value, "query parameter"), separators=(",", ":"))


def _scalar(value: object) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    raise TypeError("path values must be scalar")


def _encode_request_body(operation: OperationFacts, body: object | None) -> tuple[bytes | BinaryIO | None, str | None]:
    encoding = operation.request_body_encoding
    if encoding in ("", "none"):
        if body is not None:
            raise ValueError(f"{operation.operation_id} takes no request body")
        return None, None
    if body is None:
        raise ValueError(f"{operation.operation_id} requires a {encoding} request body")
    if encoding == "binary":
        if isinstance(body, bytes):
            return body, None
        if isinstance(body, (bytearray, memoryview)):
            return bytes(body), None
        if callable(getattr(body, "read", None)):
            # Sent once, as it is read.
            return cast(BinaryIO, body), None
        raise TypeError("a binary request body must be bytes or a binary file-like value")
    if encoding == "multipart":
        return _encode_multipart_request(body)
    if encoding != "json":
        raise ValueError(f"unsupported request encoding {encoding!r}")
    return _encode_json_body(body), "application/json"


def _encode_json_body(value: object) -> bytes:
    """The wire JSON of a contract value."""
    return json.dumps(_require_json_value(value, "request body"), separators=(",", ":"), allow_nan=False).encode("utf-8")


def _encode_multipart_request(body: object) -> tuple[bytes, str]:
    if not isinstance(body, dict):
        raise TypeError("a multipart request body must be a dictionary")
    boundary = f"aionix-{secrets.token_hex(16)}"
    encoded = bytearray()
    for name, value in body.items():
        if not isinstance(name, str) or re.fullmatch(r"[A-Za-z0-9_.-]+", name) is None:
            raise ValueError("multipart field name is invalid")
        if value is None:
            continue
        if isinstance(value, bytes):
            content = value
            content_type = "application/octet-stream"
        else:
            content = _encode_json_body(value)
            content_type = "application/json"
        encoded.extend(f"--{boundary}\r\n".encode("ascii"))
        encoded.extend(f'Content-Disposition: form-data; name="{name}"\r\n'.encode("ascii"))
        encoded.extend(f"Content-Type: {content_type}\r\n\r\n".encode("ascii"))
        encoded.extend(content)
        encoded.extend(b"\r\n")
    encoded.extend(f"--{boundary}--\r\n".encode("ascii"))
    return bytes(encoded), f"multipart/form-data; boundary={boundary}"


def _require_json_value(value: object, location: str) -> JsonValue:
    if value is None or isinstance(value, (bool, str)):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"{location} contains a non-finite number")
        return value
    if isinstance(value, list):
        return [_require_json_value(item, location) for item in value]
    if isinstance(value, dict):
        result: dict[str, JsonValue] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError(f"{location} contains a non-string key")
            result[key] = _require_json_value(item, location)
        return result
    raise ValueError(f"{location} is not JSON-compatible")


def resolve_body_resource_trn(body: object, pointer: str, required: bool) -> str | None:
    """The resource a request body names at its declared pointer. Not part
    of the public API."""
    if not pointer.startswith("/") or not isinstance(body, Mapping):
        raise ValueError("a body resource needs a JSON object and its declared pointer")
    value: object = body
    for token in pointer[1:].split("/"):
        key = token.replace("~1", "/").replace("~0", "~")
        if not isinstance(value, Mapping) or key not in value:
            if not required:
                return None
            raise ValueError("the required resource target is missing")
        value = value[key]
    if not isinstance(value, str) or not value.startswith("trn:"):
        raise ValueError("a body resource must be a nonempty TRN when present")
    return value


__all__ = (
    "CallEngine",
    "admission_not_after_for_window",
    "resolve_body_resource_trn",
)
